 renderMain();$('.work-screen')?.classList.add('check-refresh');if(modalState?.kind==='topic'&&modalState.tab==='tasks'){const topic=allTopics(data,state).find(t=>t.id===modalState.id);if(topic&&$('#topic-task-list'))$('#topic-task-list').innerHTML=authoredTaskRows(topic);}
