  <div id="work-completion">${!task&&queue.deferredCount?'<button type="button" class="button primary" data-feature="resume-all">Return to skipped tasks</button>':studyButtonMarkup({action:task?'work-complete':queue.tasksTotal?'navigate':'new-topic',id:topic?.id||'',taskId:task?.id||'',label:task?'Complete task: '+task.title:queue.tasksTotal?'Review topics':'Add a topic',text:task?'Done':queue.tasksTotal?'Review':'Add',caption:task?'NEXT TASK':queue.tasksTotal?'YOUR TOPICS':'YOUR FIRST TOPIC',glyph:task?'check':queue.tasksTotal?'book':'plus'})}</div>
