async function decodeSound(sound){
 if(soundBuffers.has(sound.id))return soundBuffers.get(sound.id);audioContext||=new(window.AudioContext||window.webkitAudioContext)();const encoded=sound.dataURL.split(',')[1],bytes=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0)),buffer=await audioContext.decodeAudioData(bytes.buffer);
 if(buffer.duration>8||buffer.duration<=0)throw new Error('Use a sound between 0 and 8 seconds long.');soundBuffers.set(sound.id,buffer);return buffer;
}
async function playCustomSound(sound){try{audioContext||=new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();const buffer=await decodeSound(sound),source=audioContext.createBufferSource(),gain=audioContext.createGain();source.buffer=buffer;gain.gain.value=Math.max(0,Math.min(1,Number(state.settings.volume)*2));source.connect(gain);gain.connect(audioContext.destination);source.start(0,0,Math.min(3,buffer.duration));}catch(error){toast('This sound could not play. Choose Studio chime or another clip.',true);}}
async function importSoundData(name,dataURL){
 try{workspace.studio||={themes:[],sounds:[]};if(workspace.studio.sounds.length>=5)throw new Error('Remove an imported sound before adding another (5 maximum).');const sound=validateSound({id:uid('sound'),name:name.slice(0,100),dataURL});await decodeSound(sound);workspace.studio.sounds.push(sound);mutate(s=>{s.settings.soundId=sound.id;s.settings.sound=true;});await commitNow();toast('Sound installed. Tap Test sound to hear it.');}catch(error){toast(error.message||'This audio format is not supported. Try MP3 or WAV.',true);}
}
$('#sound-file').addEventListener('change',async event=>{
 const file=event.target.files[0];if(!file)return;if(file.size>500000){toast('Use a sound smaller than 500 KB.',true);return;}const reader=new FileReader();reader.onerror=()=>toast('The sound file could not be read.',true);reader.onload=()=>void importSoundData(file.name,String(reader.result).replace('audio/x-m4a','audio/mp4'));reader.readAsDataURL(file);
});
