function staircaseScene(climb){
 const count=climb.steps.length,width=960,base=402,avatarIndex=climb.climbed===0&&climb.viewedLevel===1?-1:climb.steps.findIndex(s=>s.current),ground=climb.climbed===climb.first&&climb.viewedLevel===climb.level;
 const steps=climb.steps.map((step,i)=>{const x=85+i*78,y=base-(i+1)*24;return`<g role="button" tabindex="0" data-action="stair-topic" data-id="${esc(step.topicId)}" aria-label="Stair ${step.number}: ${esc(step.title)}. ${step.climbed?'Completed':'To learn'}. Open lesson" class="stair-block ${step.topicId===ui.climbTopicId?'focused':''} ${step.climbed?'climbed':''} ${step.current?'current':''} ${step.next?'next':''}"><title>${esc(step.title)}</title><rect class="stair-hit" x="${x-3}" y="${y-95}" width="78" height="${base-y+100}" fill="transparent"/><path class="stair-side" d="M${x+66} ${y}l16-12V390l-16 12Z"/><path class="stair-front" d="M${x} ${y}h66V402h-66Z"/><path class="stair-tread" d="M${x} ${y}h66l16-12h-66Z"/><path class="stair-edge" d="M${x} ${y}h66l16-12"/><text class="stair-number" x="${x+33}" y="${y+17}" text-anchor="middle">${step.number}</text>${step.next?`<text class="stair-next" x="${x+41}" y="${y-23}" text-anchor="middle">NEXT</text>`:''}${step.current?`<text class="stair-you" x="${x+41}" y="${y-83}" text-anchor="middle">YOU ARE HERE</text>`:''}</g>`;}).join('');
 const ax=ground?49:85+avatarIndex*78+38,ay=ground?base-4:base-(avatarIndex+1)*24-7;
 const avatar=ground||avatarIndex>=0?`<g class="stair-climber" transform="translate(${ax},${ay})"><ellipse cx="0" cy="1" rx="18" ry="4" class="stair-person-shadow"/><g class="stair-person"><circle cx="0" cy="-44" r="7"/><path d="M0-34v18m0-13-12 8m12-8 10 8M0-16-10-2m10-14 9 14"/></g></g>`:'';
 return`<svg class="stair-svg" viewBox="0 0 ${width} 465" role="group" aria-label="Level ${climb.viewedLevel} staircase. ${climb.climbed} of ${climb.total} stairs climbed. Each stair is one completed topic."><defs><radialGradient id="stair-glow"><stop stop-color="var(--accent)" stop-opacity=".13"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></radialGradient></defs><ellipse cx="${85+Math.max(0,count-1)*39}" cy="392" rx="${Math.max(160,count*45)}" ry="52" fill="url(#stair-glow)"/><path class="stair-ground" d="M25 403h885"/>${steps}${avatar}${ground?`<text class="stair-you" x="49" y="315" text-anchor="middle">YOU ARE HERE</text><text class="stair-ground-label" x="49" y="432" text-anchor="middle">${climb.climbed?climb.climbed+' CLIMBED':'START'}</text>`:''}</svg>`;
}
function staircaseView(){
 const climb=staircaseProgress(data,state,ui.climbLevel),courses=companionSummary(catalog,workspace).courses,totalClimbed=courses.reduce((n,c)=>n+c.completedTopics,0),upcoming=climb.nextTopicId?topicStair(data,state,climb.nextTopicId):null,start=climb.first+1,end=climb.first+climb.steps.length;
 return pageHeading('Your climb, one topic at a time.','Every completed topic earns one stair. Your level rises after each flight of up to ten stairs.',btn(icon(climb.complete?'book':'play','sm')+(climb.complete?'Explore your topics':'Continue learning'),'navigate',`data-route="${climb.complete?'topics':'work'}"`,'primary'),'Your staircase')+courseJourney('climb',ui.climbTopicId||'')+`<section class="card climb-hero"><div class="climb-summary"><div class="eyebrow">${esc(data.meta.course.title)}</div><span class="pill green">${climb.complete?'Top reached':'Level '+climb.level}</span><div class="climb-number"><strong>${climb.climbed}</strong><span>${climb.climbed===1?'stair':'stairs'} climbed<small>of ${climb.total} selected topics</small></span></div><p>${climb.complete?'You have completed every topic in your selected path.':climb.total?climb.remaining+' more '+(climb.remaining===1?'stair':'stairs')+(climb.end===climb.total?' to reach the top.':' to reach Level '+(climb.level+1)+'.'):'Add your first learning topic to begin.'}</p><div class="progress-line"><span style="width:${climb.percent}%"></span></div><small class="climb-level-progress">${climb.percent}% through Level ${climb.level}</small>${upcoming?`<div class="climb-next-progress"><span>Next stair · ${upcoming.number}</span><strong>${esc(upcoming.title)}</strong><small>${upcoming.tasksDone} / ${upcoming.tasksTotal} required tasks complete</small>${btn('Open lesson '+icon('arrow','sm'),'stair-topic',`data-id="${esc(upcoming.topicId)}"`,'text-button')}</div>`:''}</div><div class="climb-flight"><div class="climb-flight-header"><div><h2>${climb.total?'Level '+climb.viewedLevel:'Your first stair is waiting'}</h2><p>${climb.total?'Stairs '+start+'–'+end+' · tap a stair to open its lesson':'A new course starts at ground level.'}</p></div><div class="climb-flight-buttons">${btn(icon('left','sm'),'climb-prev',`${climb.viewedLevel<=1?'disabled':''} aria-label="Previous stair level"`,'ghost small')}${btn(icon('chevron','sm'),'climb-next',`${climb.viewedLevel>=climb.levels?'disabled':''} aria-label="Next stair level"`,'ghost small')}</div></div>${climb.total?`<div class="stair-viewport" tabindex="0" aria-label="Scrollable staircase">${staircaseScene(climb)}</div>`:empty('Begin with one topic','Add topics to this course, then study and mark them complete in Study.',btn('Add a topic','new-topic','','primary'))}<div class="climb-flight-footer"><label>View level <select data-climb-level aria-label="Staircase level">${options(Array.from({length:climb.levels},(_,i)=>({value:String(i+1),label:'Level '+(i+1)})),String(climb.viewedLevel))}</select></label>${btn('My position','climb-position','','ghost small')}<div class="climb-legend"><span><i></i>Climbed</span><span><i class="future"></i>Ahead</span></div></div></div></section><details class="card stair-topic-list section-gap"><summary>Topics on Level ${climb.viewedLevel}<span>${climb.steps.length} topics ${icon('down','sm')}</span></summary><div>${climb.steps.map(step=>`<button data-action="stair-topic" data-id="${esc(step.topicId)}" class="stair-topic-row ${step.topicId===ui.climbTopicId?'focused':''}"><span class="stair-topic-number ${step.climbed?'done':''}">${step.climbed?icon('check','sm'):step.number}</span><span><strong>${esc(step.title)}</strong><small>Stair ${step.number} · ${step.climbed?'Completed':step.tasksDone+' / '+step.tasksTotal+' tasks'}</small></span>${icon('chevron','sm')}</button>`).join('')}</div></details><div class="metric-grid section-gap">${metric('Stairs remaining',climb.total-climb.climbed,'In this selected course path','stairs')}${metric('Course sections finished',climb.completedStages,'Topic checklists completed','book')}${metric('Across your courses',totalClimbed,'Total topic stairs climbed','tree')}</div><section class="card section-gap"><div class="card-header"><div><h2>A separate climb for every course</h2><p>Each course keeps its own staircase and levels.</p></div>${icon('stairs')}</div><div class="course-climbs">${courses.map(course=>{const level=stairLevel(course.completedTopics,course.totalTopics);return`<button class="course-climb ${course.id===workspace.settings.activeCourseId?'active':''}" data-action="course-climb" data-id="${esc(course.id)}"><span class="course-climb-mark" style="--course-color:${esc(course.color)}">${icon('stairs')}</span><span><strong>${esc(course.title)}</strong><small>${level.complete?'Top reached':'Level '+level.level} · ${course.completedTopics} / ${course.totalTopics} stairs</small></span>${icon('arrow','sm')}</button>`;}).join('')}</div></section><p class="footer-note">One stair is awarded when a topic’s required tasks are complete or it has an independent demonstration. Individual task checkboxes move you toward a stair. Undo and backup restores update the climb automatically. Climbed stairs show completed topics first; the remaining topics follow course order. Tap any stair to open its lesson, tasks, resources, and knowledge connections.</p>`;
}

