function renderMain(){if(!data||!state||!$('#main'))return;stairObserver?.disconnect();stairObserver=null;forestController?.dispose();forestController=null;orbController?.dispose();orbController=null;document.body.dataset.page=route;document.querySelectorAll('.sidebar,.topbar,.bottom-nav,.menu-overlay').forEach(e=>e.inert=route==='forest');window.AndroidApp?.setImmersive?.(route==='forest'||studyFeaturesUI?.isFullscreen());const hasCourse=Boolean(workspace.courses[workspace.settings.activeCourseId]);$('#main').innerHTML=(!hasCourse&&COURSE_ROUTES.has(route)?emptyCourseView:views[route]||todayView)();const studyDone=$('#main [data-action=work-complete]');if(studyDone)studyDone.disabled=workBusy;$('#route-title').textContent=titles[route]||'Today';document.title=(titles[route]||'Today')+' · LW Learning Studio';document.querySelectorAll('[data-route]').forEach(a=>{const active=a.dataset.route===route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});markSaveStatus();updateTimer();startUI?.updateGreeting();updateAppNavigation();appMotion?.render(route);const extra=document.querySelector('.nav-extra-tools');if(extra)extra.open=!['dashboard','work','reminders','notebook','welcome'].includes(route);document.querySelectorAll('.side-nav a.active').forEach(a=>{let parent=a.closest('details');while(parent){parent.open=true;parent=parent.parentElement.closest('details');}});if(route==='climb'&&hasCourse){const viewport=$('.stair-viewport');if(viewport){const progress=staircaseProgress(data,state,ui.climbLevel),step=ui.climbTopicId&&progress.steps.some(s=>s.topicId===ui.climbTopicId)?progress.steps.findIndex(s=>s.topicId===ui.climbTopicId):Math.max(0,Math.min(progress.steps.length-1,progress.climbed-progress.first-1)),center=()=>{const scale=viewport.querySelector('svg').getBoundingClientRect().width/960;viewport.scrollLeft=(85+step*78+38)*scale-viewport.clientWidth/2;};center();stairObserver=new ResizeObserver(center);stairObserver.observe(viewport);}}if(route==='knowledge'&&hasCourse){const viewport=$('.knowledge-viewport'),target=viewport.querySelector('.map-node.focused');viewport.scrollLeft=(viewport.scrollWidth-viewport.clientWidth)/2;if(target){const bounds=target.getBoundingClientRect(),container=viewport.getBoundingClientRect();viewport.scrollLeft+=bounds.left-container.left-(viewport.clientWidth-bounds.width)/2;viewport.scrollTop+=bounds.top-container.top-(viewport.clientHeight-bounds.height)/2;}}if(route==='work'&&hasCourse&&$('#main .orb-stage'))orbController=bindOrb($('#main .orb-stage'),{motion:()=>!reducedMotion()});void learningUI?.hydrate();upgradesUI?.hydrate();studyFeaturesUI?.hydrate();organizerUI?.hydrate();captureUI?.hydrate();practiceUI?.hydrate();planningUI?.hydrate();assessmentsUI?.hydrate();focusUI?.hydrate();personalUI?.hydrate();noteToolsUI?.hydrate();personalWorldsUI?.hydrate();authorUI?.hydrate();dataSafetyUI?.hydrate();reminderExtrasUI?.hydrate();deviceAddonsUI?.hydrate();languageUI?.hydrate();documentUI?.hydrate();incomingUI?.hydrate();voiceUI?.hydrate();mediaToolsUI?.hydrate();if(route==='forest')forestController=forestUI.mount();}

function openModal(html,{drawer=false,kind='form',id='',date=''}={}){modalOrbController?.dispose();modalOrbController=null;const modal=$('#modal');if(modal.open)modal.close();else opener=document.activeElement;modal.className=drawer?'drawer':'';modal.innerHTML=html;modalState={kind,id,date};modal.showModal();appMotion?.sheetOpened(modal);}
function closeModal(){modalOrbController?.dispose();modalOrbController=null;const modal=$('#modal');if(modal.open)modal.close();modalState=null;updateAppNavigation();if(opener?.isConnected)opener.focus();}
function modalHead(title,subtitle='',id=''){return`<div class="dialog-head"><div>${id?`<span class="mono">${esc(id)}</span>`:''}<h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div>`;}
function formModal(type,title,fields,{subtitle='',id='',date='',extra='',button='Save',footer=''}={}){openModal(`<div class="dialog-content">${modalHead(title,subtitle,id)}${extra}<form data-form="${type}" data-id="${esc(id)}" data-date="${esc(date)}"><div class="form-grid">${fields}</div><div class="form-error" role="alert"></div><div class="form-actions">${footer}<button type="button" class="button ghost" data-action="close-modal">Cancel</button><button type="submit" class="button primary">${esc(button)}</button></div></form></div>`,{kind:type,id,date});}
function topicOptions(selected='',optional=false){return[{value:'',label:optional?'No linked topic':'Choose a topic'},...allTopics(data,state).map(t=>({value:t.id,label:t.id+' · '+t.title}))];}
function topicModal(id,tab='overview'){const topic=allTopics(data,state).find(t=>t.id===id);if(!topic){toast('Topic not found.',true);return;}const p=topicProgress(topic,state),resources=topic.resources.map(id=>allResources(data,state).find(r=>r.id===id)).filter(Boolean),tools=topic.tools.map(id=>allTools(data,state).find(t=>t.id===id)).filter(Boolean);let content='';
 if(tab==='overview')content=`<div class="detail-section"><h3>Deep study scope</h3><p>${esc(topic.scope)}</p></div><div class="detail-section"><h3>Practice task</h3><p>${esc(topic.practice)}</p></div><div class="detail-section"><h3>Evidence to save</h3><p>${esc(topic.evidenceRequired)}</p></div><div class="detail-section"><h3>Prerequisites</h3><p>${topic.requires?.length?topic.requires.map(id=>{const parent=allTopics(data,state).find(t=>t.id===id);return`<button class="text-button" data-action="topic" data-id="${esc(id)}">${esc(parent?.title||id)} ${icon('arrow','sm')}</button>`;}).join(''):esc(topic.prerequisites||'None')}</p></div><div class="detail-section"><h3>Related projects</h3><div class="pills">${topic.projects.map(id=>`<button class="button ghost small" data-action="project" data-id="${id}">${id}</button>`).join('')||'<p class="quiet-note">Add a related project as you build this skill.</p>'}</div></div><div class="button-row">${btn(`${icon('today','sm')}Add practice to today`,'topic-today',`data-id="${id}"`,'primary')}${btn(`${icon('clock','sm')}Log a session`,'session',`data-topic="${id}"`,'ghost')}${btn(`${icon('note','sm')}Write a note`,'note',`data-topic="${id}"`,'ghost')}</div>`;
 if(tab==='tasks')content=`<div class="detail-section"><h3>Course task checklist</h3><p>Follow the tasks in order. Each required checkbox must be checked before its task can be completed. Progress is shared with Work and Today.</p></div><div id="topic-task-list">${authoredTaskRows(topic)}</div>`;
 if(tab==='resources')content=`<div class="detail-section"><h3>Suggested learning resources</h3><p>Use the relevant section for this topic. A reference can cover several subjects in the same domain.</p></div>${resources.map(r=>`<a class="detail-resource" href="${esc(safeURL(r.url))}" target="_blank" rel="noopener noreferrer">${icon('link')}<div><h3><button class="resource-title" data-action="resource" data-id="${r.id}">${esc(r.title)}</button></h3><p>${esc(r.use)}</p><small>${r.id} · ${esc(r.publisher)} · ${esc(r.level)}</small></div>${icon('external','sm')}</a>`).join('')||empty('No linked resources yet','Add a resource to your library and connect its ID in a custom topic.')}<div class="detail-section section-gap"><h3>Suggested tools</h3><div class="pills">${tools.map(t=>`<button class="button small ghost" data-action="tool" data-id="${t.id}">${esc(t.title)}</button>`).join('')||'<p class="quiet-note">Use the tools appropriate to your exercise.</p>'}</div></div>`;
 if(tab==='tracking')content=`<div class="button-row">${topicBadge(topic)}${pill(duration(topicMinutes(id,state))+' logged')}${reviewDate(topic,state)?pill('Review '+prettyDate(reviewDate(topic,state),true),reviewDate(topic,state)<=isoDate()?'amber':''):''}</div><div class="evidence-status ${isVerified(topic,state)?'':'warning'}">${isVerified(topic,state)?'Independent demonstration recorded.':p.status==='Complete'?'Complete needs proficiency 3+, evidence, and a demonstration date.':'Practice until you can demonstrate this skill without a walkthrough.'}</div><form data-form="topic-progress" data-id="${id}"><div class="form-grid">${selectField('Study status','status',TOPIC_STATUSES,p.status)}${selectField('Proficiency','proficiency',RUBRIC.map((label,i)=>({value:String(i),label:i+' · '+label})),String(p.proficiency))}${inputField('Target date','targetDate',p.targetDate,'date')}${inputField('Last demonstrated','demonstratedDate',p.demonstratedDate,'date')}${inputField('Review every (days)','reviewDays',p.reviewDays,'number','min="1" max="3650" required')}${inputField('Evidence reference or private path','evidence',p.evidence,'text','maxlength="2000"')}${textField('Your learning notes','notes',p.notes)}<label class="checkbox-row field full"><input type="checkbox" name="included" ${p.included?'checked':''}>Include this topic in my selected path</label></div><div class="form-error" role="alert"></div><div class="form-actions"><button type="submit" class="button primary">Save progress</button></div></form>`;
 openModal(`<div class="dialog-content">${modalHead(topic.title,topic.stage+' · '+topic.domainName+' · '+fmtHours(topic.hours)+' initial estimate',topic.id)}${topicConnections(topic)}${learningUI?.topicExtras(topic)||''}${studyFeaturesUI?.topicNotes(topic)||''}<div class="dialog-tabs">${[['overview','Study & practice'],['tasks','Task checklist'],['resources','Resources & tools'],['tracking','Your progress']].map(([key,label])=>`<button class="dialog-tab ${tab===key?'active':''}" data-action="topic-tab" data-tab="${key}" data-id="${id}">${label}</button>`).join('')}</div>${content}</div>`,{drawer:true,kind:'topic',id});modalState.tab=tab;}
function projectModal(id){const p=allProjects(data,state).find(p=>p.id===id);if(!p)return;const current=projectProgress(p,state);formModal('project-progress',p.title,selectField('Status','status',PROJECT_STATUSES,current.status)+inputField('Target date','targetDate',current.targetDate,'date')+inputField('Reviewed date','reviewedDate',current.reviewedDate,'date')+inputField('Evidence reference','evidence',current.evidence)+textField('Your project notes','notes',current.notes),{id,subtitle:p.stage+' · '+p.hours+'h initial estimate',extra:`<div class="detail-section"><h3>Work to perform</h3><p>${esc(p.task)}</p></div><div class="detail-section"><h3>Acceptance evidence</h3><p>${esc(p.evidenceRequired)}</p></div><div class="detail-section"><h3>Suggested tools</h3><p>${esc(p.toolsText||'Use appropriate tools for this project.')}</p></div><div class="button-row">${btn('Add a project task','project-task',`data-id="${id}"`,'ghost small')}</div><div class="dialog-divider"></div>`,button:'Save project'});}
