function sessionModal(id='',topicId='',date=isoDate(),fromTimer=false){const s=state.sessions.find(s=>s.id===id)||{date,topicId:topicId||focusTopic(data,state)?.id||'',activity:'Study',minutes:fromTimer?Math.max(1,Math.round(timerElapsed()/60000)):30,projectId:state.timer?.projectId||'',work:fromTimer?state.timer?.title||'':'',outcome:'',evidence:'',nextAction:''};formModal('session',id?'Edit study session':'Log your study session',inputField('Study date','date',s.date,'date','required')+inputField('Actual minutes studied','minutes',s.minutes,'number','min="1" max="1440" required')+selectField('Topic','topicId',topicOptions(s.topicId),s.topicId,true)+selectField('Activity','activity',ACTIVITIES,s.activity)+inputField('Project ID (optional)','projectId',s.projectId)+textField('What did you work on?','work',s.work)+textField('Outcome or lesson','outcome',s.outcome)+inputField('Evidence reference','evidence',s.evidence,'text','',true)+textField('Next action','nextAction',s.nextAction),{id,date,subtitle:'Use actual study time. The charts update from this record.',button:'Save session',extra:fromTimer?'<p class="quiet-note" style="margin-bottom:20px">Adjust the time to exclude breaks or interruptions.</p>':'',footer:id?btn('<span data-ui-text>Delete</span>','session-delete',`data-id="${id}"`,'danger ghost'):''});if(fromTimer)$('#modal form').dataset.fromTimer='true';}
