function forestLandscape(records){return`<section class="card forest-overview"><div class="card-header"><div><h2>Your growing forest</h2><p>${records.length} courses planted. Tap a tree to explore its stairs and learning topics.</p></div>${btn('Full forest '+icon('external','sm'),'navigate','data-route="forest"','ghost small')}</div><div class="forest-landscape">${records.map(r=>`<button class="forest-plant" data-action="course-climb" data-id="${r.course.id}" aria-label="Open ${esc(r.course.title)} staircase">${growthSVG(r.data,r.state)}<strong>${esc(r.course.title)}</strong><small>${treeGrowth(r.data,r.state).tasks} tasks · ${staircaseProgress(r.data,r.state).climbed} stairs</small></button>`).join('')}<button class="forest-plant forest-new" data-action="new-course" aria-label="Plant a new course tree">${icon('plus')}<strong>Plant a new path</strong><small>Your forest can keep growing</small></button></div></section>`;}
