function addCoursePack(pack,{dailyMinutes=30,weeklyHours=3}={}){workspace.customCourses.push(pack);workspace.courses[pack.meta.course.id]=defaultState(pack);workspace.courses[pack.meta.course.id].settings.dailyMinutes=Number(dailyMinutes);workspace.courses[pack.meta.course.id].settings.weeklyHours=Number(weeklyHours);completeProfile(pack.meta.course.id);selectCourse(pack.meta.course.id);closeModal();toast(pack.meta.course.title+' is ready.'+(pack.topics.length?' Open Study to begin.':' Add your first topic.'));}

