 if(input.matches('[data-day-picker]')&&input.value){ui.plannerDate=input.value;navTo('planner');if(route==='planner')renderMain();return;}
 if(input.matches('[data-preference]')){const name=input.dataset.preference;mutate(s=>s.settings[name]=input.type==='checkbox'?input.checked:Number(input.value),{render:false});return;}
 if(input.matches('[data-filter]')&&input.tagName!=='INPUT'||input.matches('[data-filter][type=checkbox]')){const key=input.dataset.filter;ui[key]=input.type==='checkbox'?input.checked:input.value;if(key==='analyticsDays')ui[key]=Number(ui[key]);if(key==='mapSearch')ui.mapFocus='';ui.topicPage=1;renderMain();}
